        load = 0; #10;
        repeat (10) begin
            #10;
            if (tc !== 1'b0) errors = errors + 1;
        end
        #10; // Final check
        if (tc !== 1'b1) errors = errors + 1;

        // Test case 6: Load with 0 again, expect tc = 1
        load = 1; data = 10'd0; #10;
        load = 0; #10;
        if (tc !== 1'b1) errors = errors + 1;

        // Final results
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
